MOD = 1000000007

def count_edges(n):
    return (2**n - 1) % MOD

def perform_mirror_right(tree, n):
    edges = 0
    level = 0
    nodes_in_level = 1
    while nodes_in_level <= len(tree):
        for i in range(nodes_in_level):
            if tree[nodes_in_level - 1 + i] != -1:
                if nodes_in_level - 1 + i * 2 + 1 < len(tree) and tree[nodes_in_level - 1 + i * 2 + 1] != -1:
                    edges += 1
                if nodes_in_level - 1 + i * 2 + 2 < len(tree) and tree[nodes_in_level - 1 + i * 2 + 2] != -1:
                    edges += 1
        nodes_in_level *= 2
    return edges

