                if nodes_in_level - 1 + i * 2 + 1 < len(tree) and tree[nodes_in_level - 1 + i * 2 + 1] != -1:
                    edges += 1
        nodes_in_level *= 2
    return edges

def perform_mirror_top(tree, n):
    edges = 0
    for i in range(len(tree)):
        if tree[i] != -1:
            if i * 2 + 1 < len(tree) and tree[i * 2 + 1] != -1:
                edges += 1
            if i * 2 + 2 < len(tree) and tree[i * 2 + 2] != -1:
                edges += 1
    return edges

