            if i * 2 + 1 < len(tree) and tree[i * 2 + 1] != -1:
                edges += 1
            if i * 2 + 2 < len(tree) and tree[i * 2 + 2] != -1:
                edges += 1
    return edges

def main():
    n, q = map(int, input().split())
    tree = [-1] * (2**(n+1) - 1)
    initial_edges = count_edges(n)

    for _ in range(q):
        query = list(map(int, input().split()))
        if query[0] == 1:
            x = query[1]
            if x == 1:
                initial_edges = (initial_edges + perform_mirror_right(tree, n)) % MOD
            elif x == 2:
                initial_edges = (initial_edges + perform_mirror_left(tree, n)) % MOD
            elif x == 3:
                initial_edges = (initial_edges + perform_mirror_top(tree, n)) % MOD
            elif x == 4:
                initial_edges = (initial_edges + perform_mirror_bottom(tree, n)) % MOD
        elif query[0] == 2:
            print(initial_edges)

